// Brazilian Portuguese texts of catalog.mjs: [English text, Portuguese text], in catalog order. The English side must
// match the T() text exactly (the build names any text without a translation and any entry whose English text changed
// or went away). Terms follow the app (src/Filee.App/Assets/i18n/pt-BR.json): predefinição (preset), motor / motores
// opcionais (engines), menu circular (donut), pastas monitoradas (watch folders), área de soltar (drop zone),
// preset names as in the app (Comprimir PDF, Vetorizar em SVG…).

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `vídeo e áudio, extração de legendas e salvamento em HEIC`],
  [`older office formats such as DOC, PPT and ODT`,
    `formatos de escritório mais antigos, como DOC, PPT e ODT`],
  [`rare e-book formats and MOBI/AZW3 output`,
    `formatos raros de e-book e saída em MOBI/AZW3`],
  [`EPS and PostScript`,
    `EPS e PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc e outras linguagens de marcação, Word → Markdown e Markdown → slides`],

  // Options
  [`quality`, `qualidade`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Qualidade ajustável para JPG, WEBP e AVIF: o JPG é salvo com 90% por padrão, e uma predefinição JPG 70% gera arquivos menores.`],
  [`resize`, `redimensionar`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Redimensione durante a conversão, por porcentagem (por exemplo, metade do tamanho) ou até um limite para o lado maior.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Defina o DPI gravado na imagem, por exemplo 300 para impressão.`],
  [`grayscale`, `tons de cinza`],
  [`A grayscale preset makes black-and-white copies.`,
    `Uma predefinição de tons de cinza cria cópias em preto e branco.`],
  [`metadata`, `metadados`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Os metadados (EXIF, XMP, perfil de cor) são mantidos por padrão e podem ser removidos por privacidade.`],
  [`ICO sizes`, `tamanhos de ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `Arquivos ICO contêm 256, 128, 64, 48, 32 e 16 px por padrão; os tamanhos podem ser alterados na predefinição.`],
  [`TIFF compression`, `compressão TIFF`],
  [`TIFF compression can be chosen (LZW by default).`,
    `Você pode escolher a compressão TIFF (LZW por padrão).`],
  [`white background`, `fundo branco`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `O JPG não tem transparência, então as áreas transparentes são preenchidas com branco.`],
  [`merge into one PDF`, `mesclar em um PDF`],
  [`The merge preset combines all dropped files into one PDF.`,
    `A predefinição Mesclar PDF junta todos os arquivos que você arrastar em um único PDF.`],
  [`split pages`, `dividir páginas`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `A predefinição Dividir PDF salva cada página como um PDF separado, em uma subpasta.`],
  [`rotate & flip`, `girar e espelhar`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `As predefinições Girar e Espelhar giram imagens para a esquerda, para a direita ou 180° e as espelham, depois de aplicar a orientação da própria foto.`],
  [`Trace to SVG`, `Vetorizar em SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Duas predefinições transformam uma imagem em formas vetoriais: Vetorizar em SVG, com até 64 cores, e Traço em SVG, em preto, para logotipos, assinaturas e digitalizações. Nenhum outro programa é necessário.`],
  [`remove background`, `remover fundo`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `A predefinição Remover fundo deixa transparente um fundo liso: o papel atrás de uma assinatura ou carimbo, o fundo de um logotipo.`],
  [`page ranges`, `intervalos de páginas`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Intervalos de páginas como 1-3,5 limitam a conversão às páginas de que você precisa.`],
  [`render DPI`, `DPI de renderização`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `As páginas são renderizadas a 150 DPI por padrão; escolha 300 DPI para qualidade de impressão.`],
  [`one long image`, `uma imagem longa`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `A predefinição Imagem longa empilha todas as páginas em uma única imagem alta, por exemplo para publicar um documento inteiro de uma vez.`],
  [`compress PDF`, `comprimir PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `A predefinição Comprimir PDF deixa um PDF menor sem que ele deixe de ser PDF: as imagens são reduzidas para 72, 150 ou 300 dpi e as fotos são salvas de novo como JPEG, enquanto textos, fontes, links, marcadores e formulários permanecem. Um PDF que não tem como ficar menor é mantido como estava. Com o Ghostscript instalado, o Filee também tenta com ele e fica com o resultado menor.`],
  [`a picture per slide`, `uma imagem por slide`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `O PPTX (slides) coloca uma imagem de cada página em um slide próprio, no tamanho da página, com o texto da página nas anotações do apresentador. Os slides ficam idênticos ao PDF, mas não são editáveis; converta para DOCX se quiser texto editável.`],
  [`vector PDF`, `PDF vetorial`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `O PDF continua vetorial, então fica nítido em qualquer zoom e na impressão.`],
  [`editable`, `editável`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `O resultado tem texto e parágrafos de verdade, que você pode editar, e não imagens das páginas.`],
  [`attachments as ZIP`, `anexos em ZIP`],
  [`Attachments can be saved separately as one ZIP.`,
    `Os anexos podem ser salvos à parte, em um único ZIP.`],
  [`one CSV per sheet`, `um CSV por planilha`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Pastas de trabalho com várias planilhas geram um CSV por planilha.`],
  [`layout kept`, `layout mantido`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Mantém o tamanho da página e as margens, cabeçalhos e rodapés com números de página, tabelas, caixas de texto, formas e imagens.`],
  [`no Office needed`, `sem precisar do Office`],
  [`No Microsoft Office or LibreOffice needed.`,
    `Não precisa do Microsoft Office nem do LibreOffice.`],
  [`no Hancom Office needed`, `sem precisar do Hancom Office`],
  [`No Hancom Office and no approval dialog.`,
    `Sem Hancom Office e sem caixa de diálogo de aprovação.`],
  [`no AutoCAD needed`, `sem precisar do AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`,
    `Não precisa do AutoCAD nem de um visualizador de DWG.`],
  [`no re-encoding`, `sem recodificação`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Quando o novo formato comporta o vídeo e o som como estão (um MOV do iPhone → MP4), eles só são reempacotados: sem perda de qualidade, com o HDR mantido, em questão de segundos.`],
  [`720p option`, `opção 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `A predefinição MP4 720p reduz vídeos grandes para compartilhar.`],
  [`extract audio`, `extrair áudio`],
  [`Only the sound is saved, without the video track.`,
    `Só o som é salvo, sem a faixa de vídeo.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `A predefinição MP3 128k gera arquivos menores, ideal para voz.`],
  [`extract`, `extrair`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Já a predefinição Extrair descompacta o arquivo em uma pasta.`],
  [`pack into one ZIP`, `compactar em um ZIP`],
  [`Any selection of files can be packed into one ZIP.`,
    `Qualquer seleção de arquivos pode ser compactada em um único ZIP.`],
  [`DRM-free books`, `livros sem DRM`],
  [`Works with DRM-free books only.`,
    `Funciona apenas com livros sem DRM.`],
  [`ALAC in M4A`, `ALAC em M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`,
    `O M4A pode conter ALAC sem perdas, além de AAC.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `As predefinições de vídeo podem codificar em HEVC (H.265) ou AV1 para gerar arquivos menores, mantendo vídeo de 10 bits e HDR.`],
  [`hardware encoding`, `codificação por hardware`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Ative Usar aceleração de hardware em uma predefinição de vídeo para codificar H.264 e HEVC no chip gráfico (NVENC, Quick Sync, AMF, VideoToolbox ou VA-API): muito mais rápido e econômico em energia, com arquivos um pouco maiores na mesma qualidade. Vem desativado por padrão e, sem um chip compatível, o vídeo é codificado como antes.`],
  [`every frame`, `todos os quadros`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Normalmente um vídeo gera um único quadro estático. As predefinições Extrair quadros, ou a opção Salvar cada quadro de um vídeo em uma predefinição PNG ou JPG, salvam todos os quadros (ou um a cada N) como imagens em uma pasta ao lado do vídeo.`],
  [`extract subtitles`, `extrair legendas`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `A predefinição Extrair legendas, no menu circular de vídeo, salva a primeira faixa de legendas em texto de um vídeo como SRT.`],
  [`saved as UTF-8`, `salvo em UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Os resultados são salvos em UTF-8. Arquivos coreanos salvos em CP949 (EUC-KR) são detectados e lidos corretamente.`],
  [`tables to CSV / Excel`, `tabelas para CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Dados em forma de tabela (uma lista de registros) também convertem de e para CSV e Excel.`],
  [`picture preview`, `prévia em imagem`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG ou JPG gera uma imagem sombreada do modelo, vista pela frente, à direita e de cima.`],
  [`colours and textures`, `cores e texturas`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Cores, texturas e materiais são mantidos quando o formato de destino os comporta. O STL mantém só a forma.`],
  [`HDR tone-mapped`, `HDR com mapeamento de tons`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `Capturas de tela HDR que o Windows salva como JPEG XR passam por mapeamento de tons para o brilho normal, em vez de ficarem estouradas.`],
  [`Live Photo video`, `vídeo da Live Photo`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `A predefinição Extrair vídeo da Live Photo salva o vídeo de uma Live Photo do iPhone (um LIVP do iCloud ou uma foto com seu MOV) ou de uma Motion Photo do Android como MP4 ou MOV. No sentido inverso, as predefinições Live Photo (iPhone) e Motion Photo (Android) transformam um trecho curto de um vídeo em uma foto com movimento; isso ainda é experimental.`],
  [`WGS 84 longitude / latitude`, `longitude / latitude WGS 84`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Os resultados são sempre em longitude e latitude (WGS 84). Shapefiles em UTM, Web Mercator, Lambert ou Albers são convertidos e abrem no lugar certo; converter um arquivo para o próprio formato o reprojeta.`],
  [`save as ZIP`, `salvar como ZIP`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Um Shapefile é composto de cinco arquivos (.shp, .shx, .dbf, .prj e .cpg). Com Salvar o resultado como ZIP em uma predefinição, ou para todo resultado geoespacial nas configurações, eles ficam juntos em um único ZIP.`],
  [`Canon CR2 RAW photo`, `Foto RAW Canon CR2`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 é o formato de foto RAW que as DSLRs da Canon usaram por muitos anos (os modelos mais novos da Canon gravam CR3). Ele guarda os dados brutos do sensor, o que deixa bastante margem para edição.`],
  [`Nikon NEF RAW photo`, `Foto RAW Nikon NEF`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF é o formato de foto RAW da Nikon, usado pelas DSLRs e pelas câmeras mirrorless Z da Nikon. Como outros arquivos RAW, ele guarda os dados brutos do sensor e é várias vezes maior que um JPG.`],

  // Images
  [`Images`, `Imagens`],
  [`images`, `imagens`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Fotos e gráficos, incluindo HEIC e Live Photos do iPhone, PSD do Photoshop, RAW de câmera de todas as grandes marcas, APNG animado, DICOM e as capturas de tela HDR do Windows (JPEG XR). Redimensione, gire, defina qualidade e DPI ou remova metadados durante a conversão, ou vetorize uma imagem em SVG.`],
  [`JPEG image`, `Imagem JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG é o formato de foto mais usado. Sua compressão com perdas mantém os arquivos pequenos, mas cada salvamento em qualidade menor descarta alguns detalhes, e ele não tem transparência.`],
  [`PNG image`, `Imagem PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG é um formato de imagem sem perdas e com transparência, ideal para capturas de tela, logotipos e gráficos com bordas nítidas. Fotos salvas em PNG costumam ficar bem maiores que em JPG.`],
  [`WebP image`, `Imagem WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP é o formato de imagem do Google para a web. Ele suporta compressão com e sem perdas e transparência, e costuma ser menor que JPG ou PNG, mas alguns editores e formulários de upload ainda não o aceitam.`],
  [`AVIF image`, `Imagem AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF é um formato de imagem moderno baseado no codec de vídeo AV1. Ele comprime melhor que JPG e WebP, mas o suporte em programas e dispositivos mais antigos ainda é limitado.`],
  [`HEIC / HEIF image`, `Imagem HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF) é o formato de foto que iPhones e iPads usam por padrão. As fotos costumam ter cerca de metade do tamanho de um JPG, mas muitos apps do Windows, sites e dispositivos mais antigos não conseguem abri-las.`],
  [`GIF image / animation`, `Imagem / animação GIF`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF é um formato de imagem antigo, limitado a 256 cores, que suporta animações simples. Ainda é a forma universal de compartilhar loops curtos e sem som em chats, documentos e relatórios de bugs.`],
  [`Windows icon`, `Ícone do Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO é o formato de ícone do Windows. Um único arquivo ICO guarda a mesma imagem em vários tamanhos (por exemplo 16, 32, 48 e 256 pixels), para que ela fique nítida em todo lugar, da barra de tarefas aos favicons de sites.`],
  [`Photoshop document`, `Documento do Photoshop`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD é o formato nativo do Adobe Photoshop. Ele mantém camadas, máscaras e ajustes, por isso é ótimo para edição, mas a maioria dos visualizadores e sites não consegue abri-lo.`],
  [`macOS icon`, `Ícone do macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS é o formato de ícone do macOS. Como o ICO, ele reúne vários tamanhos de uma imagem, até 1024×1024 para telas Retina, e é usado nos ícones de apps no Mac.`],
  [`Camera RAW`, `RAW de câmera`],
  [`Windows only`, `somente no Windows`],
  [`the photo of the Live Photo`, `a foto da Live Photo`],
  [`the video of the Live Photo`, `o vídeo da Live Photo`],

  // Vector graphics
  [`Vector graphics`, `Gráficos vetoriais`],
  [`vector graphics`, `gráficos vetoriais`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, metarquivos do Windows, Illustrator, EPS/PostScript e desenhos do CorelDRAW, do Visio e do LibreOffice Draw. O SVG também vira DXF ou DWG para CAD.`],
  [`SVG vector graphic`, `Gráfico vetorial SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG é um formato de gráficos vetoriais baseado em XML. Formas e textos ficam nítidos em qualquer tamanho, o que o torna ideal para logotipos e ícones na web, mas muitos apps e formulários de upload só aceitam imagens em pixels.`],
  [`Encapsulated PostScript`, `PostScript encapsulado`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS é um formato vetorial do mundo da impressão e do design, muito usado para logotipos e ilustrações enviados a gráficas. A maioria dos apps modernos não consegue exibi-lo sem um interpretador PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `arquivos AI salvos com conteúdo PDF (o padrão do Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `Transforme PDFs em imagens, documentos editáveis do Word ou HWPX, slides do PowerPoint, texto ou um arquivo de quadrinhos, e mescle, divida, comprima ou escolha páginas.`],
  [`PDF document`, `Documento PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF é o padrão para compartilhar documentos que precisam ter a mesma aparência em qualquer lugar. Fontes, layout e imagens são fixos, e ele abre em qualquer dispositivo. Por isso mesmo, PDFs são difíceis de editar.`],
  [`one page`, `uma página`],

  // Documents
  [`Documents`, `Documentos`],
  [`documents`, `documentos`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Documentos do Word sem o Microsoft Office, notas fiscais eletrônicas chinesas em OFD, formatos de processadores de texto antigos e raros com o motor opcional LibreOffice, e e-mails salvos (EML e MSG do Outlook).`],
  [`Word document`, `Documento do Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX é o formato do Microsoft Word desde o Word 2007 (Office Open XML). É o formato mais comum para documentos editáveis, como relatórios, cartas e formulários.`],
  [`Word 97–2003 document`, `Documento do Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC é o formato binário do Word 97–2003. Acervos antigos, formulários oficiais e sistemas legados ainda o geram, mas ele está sendo substituído pelo DOCX.`],
  [`E-mail message`, `Mensagem de e-mail`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML é um único e-mail salvo como arquivo (formato MIME), com os cabeçalhos, a mensagem e os anexos. A maioria dos apps de e-mail, incluindo o Outlook e o Thunderbird, consegue abri-lo.`],
  [`Outlook message`, `Mensagem do Outlook`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG é o arquivo que o Microsoft Outlook salva quando você arrasta um e-mail para fora dele. Só o Outlook o abre, então é difícil lê-lo em um PC sem Outlook ou no celular.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `HWP/HWPX coreano`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Documentos coreanos do Hancom Hangul sem o Hancom Office: HWP ↔ HWPX, para PDF, imagens, Word, texto, Markdown e HTML, e HWPX a partir de Word, Excel, PowerPoint, Markdown e PDF.`],
  [`Hangul document (HWP)`, `Documento do Hangul (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP é o formato de documento do Hancom Office Hangul (한글), o processador de texto padrão em órgãos públicos, escolas e muitas empresas da Coreia. Fora da Coreia, poucos programas conseguem abri-lo.`],
  [`Hangul document (HWPX)`, `Documento do Hangul (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX é o formato aberto, baseado em XML, do Hancom Hangul (OWPML, norma nacional coreana KS X 6101). As instituições públicas coreanas estão migrando do formato binário HWP para ele.`],

  // Spreadsheets
  [`Spreadsheets`, `Planilhas`],
  [`spreadsheets`, `planilhas`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Planilhas do Excel, OpenDocument e CSV/TSV, para PDF com ajuste de página como no Excel ou entre si, sem o Excel.`],
  [`Excel workbook`, `Pasta de trabalho do Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX é o formato de pasta de trabalho do Microsoft Excel desde o Excel 2007. Uma pasta de trabalho pode ter várias planilhas com fórmulas, formatação, gráficos e imagens.`],
  [`Excel 97–2003 workbook`, `Pasta de trabalho do Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS é o formato binário de pasta de trabalho do Excel 97–2003. Muitos sistemas antigos e exportações de bancos ou de contabilidade ainda o geram.`],
  [`Comma-separated values`, `Valores separados por vírgula`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV é texto simples com uma linha da tabela por linha do arquivo. Todo programa de planilhas, banco de dados e linguagem de programação consegue lê-lo, mas ele não tem formatação, fórmulas nem várias planilhas.`],

  // Presentations
  [`Presentations`, `Apresentações`],
  [`presentations`, `apresentações`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint para PDF, imagens e HWPX sem o PowerPoint; PPT antigo, ODP e Keynote com o motor opcional LibreOffice.`],
  [`PowerPoint presentation`, `Apresentação do PowerPoint`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX é o formato do Microsoft PowerPoint desde o PowerPoint 2007. Ele contém slides com texto, imagens, formas, tabelas, anotações e animações.`],
  [`PowerPoint 97–2003 presentation`, `Apresentação do PowerPoint 97–2003`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT é o formato binário do PowerPoint 97–2003. Slides de aulas antigas e apresentações arquivadas muitas vezes ainda estão em PPT.`],

  // Text & markup
  [`Text & markup`, `Texto e marcação`],
  [`text and markup`, `texto e marcação`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Texto simples, Markdown, HTML e páginas da web salvas (MHTML) para PDF, Word, HWPX e EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter e outras linguagens de marcação usam o motor opcional Pandoc, que também transforma Markdown em slides do PowerPoint.`],
  [`Plain text`, `Texto simples`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT é texto simples sem nenhuma formatação, o formato de documento mais simples e portátil. A única coisa que pode variar é a codificação de caracteres (UTF-8, UTF-16 ou uma página de código legada).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown é uma linguagem de marcação leve em texto simples: # para títulos, * para listas, ** para negrito. É popular para anotações, arquivos README e documentação, e dá para ler mesmo sem renderizar.`],
  [`Web page (HTML)`, `Página da web (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML é a linguagem das páginas da web. Um arquivo .html salvo abre em qualquer navegador, mas a aparência depende do navegador e dos estilos e imagens vinculados, que podem faltar quando você está offline.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `arquivos LOG e scripts (PY, PAC, BAT, COMMAND) são lidos como texto e nunca executados`],
  [`the saved page, with its pictures`, `a página salva, com as imagens`],

  // Data
  [`Data`, `Dados`],
  [`data files`, `arquivos de dados`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML e XML entre si, e tabelas de e para CSV e Excel. Contatos vCard de e para CSV, inclusive de celulares antigos. Não é preciso instalar nada.`],
  [`JSON data`, `Dados JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON é o formato de dados da web: objetos, listas, textos e números em texto simples. APIs, apps e arquivos de configuração o usam por toda parte.`],
  [`YAML data`, `Dados YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML guarda o mesmo tipo de dados que o JSON, escrito com indentação em vez de chaves. Arquivos de configuração do Docker, do Kubernetes, de pipelines de CI e de muitos apps são em YAML.`],
  [`vCard contacts`, `Contatos vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf) é o arquivo padrão de contatos. Celulares, Outlook, Google Contatos e iCloud exportam agendas como vCard, muitas vezes com vários contatos em um só arquivo.`],

  // E-books
  [`E-books & comics`, `E-books e quadrinhos`],
  [`e-books and comics`, `e-books e quadrinhos`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook e arquivos de quadrinhos (CBZ, CBR, CB7…) para PDF, EPUB, Word e mais, e KEPUB para leitores Kobo. Apenas livros sem DRM.`],
  [`EPUB e-book`, `E-book EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB é o padrão aberto para e-books. O texto se ajusta a qualquer tela, e a maioria dos leitores digitais e apps de leitura o suporta; o Kindle aceita EPUB pelo Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `E-book Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI é o antigo formato de e-book da Mobipocket que o Amazon Kindle usou por anos. Ele ainda é comum em coleções de e-books mais antigas, mas a Amazon passou a usar AZW3/KFX e EPUB.`],

  // Video
  [`Video`, `Vídeo`],
  [`video`, `vídeo`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Todos os formatos de vídeo comuns para MP4 (H.264, HEVC ou AV1), WebM, MOV, MKV, AVI, GIF ou APNG, com opção de 720p, codificação por hardware no chip gráfico, extração de áudio para MP3 ou M4A e todos os quadros salvos como imagens. Usa o motor opcional FFmpeg.`],
  [`MPEG-4 video`, `Vídeo MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Parte 14) é o formato de vídeo mais compatível. Ele roda em celulares, TVs, navegadores e todos os sites de vídeo, geralmente com vídeo H.264 ou H.265 e áudio AAC.`],
  [`QuickTime movie`, `Filme QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV é o formato de vídeo QuickTime da Apple, usado por iPhones e Macs. Normalmente contém vídeo H.264 ou HEVC, mas alguns editores, TVs e sites lidam melhor com MP4.`],
  [`Matroska video`, `Vídeo Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska) é um contêiner aberto e flexível que pode conter muitas faixas de vídeo, áudio e legendas. É popular para filmes e gravações, mas celulares, TVs e editores nem sempre o reproduzem.`],
  [`WebM video`, `Vídeo WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM é um formato de vídeo aberto feito para navegadores (vídeo VP8/VP9 ou AV1 com áudio Vorbis ou Opus). Gravações de tela e downloads costumam ser WebM, mas muitos editores e dispositivos esperam MP4.`],
  [`AVI video`, `Vídeo AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI é o contêiner de vídeo da Microsoft dos anos 1990. Filmadoras, câmeras antigas e acervos ainda guardam arquivos AVI, que costumam ser grandes e têm pouco suporte em celulares.`],
  [`one still frame or every frame`, `um quadro estático ou todos os quadros`],

  // Audio
  [`Audio`, `Áudio`],
  [`audio`, `áudio`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Músicas, gravações e notas de voz para MP3, M4A, WAV, FLAC, OGG, Opus, AAC ou WavPack e TTA sem perdas. APE, DSD e DTS também são lidos. Usa o motor opcional FFmpeg.`],
  [`MP3 audio`, `Áudio MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 é o formato clássico de áudio comprimido. Praticamente todo player, som de carro e celular o reproduz, o que faz dele a escolha mais segura para compartilhar músicas, podcasts e gravações.`],
  [`MPEG-4 audio`, `Áudio MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A é um arquivo de áudio MPEG-4, geralmente AAC, usado pelo iTunes, pelas notas de voz do iPhone e por muitos gravadores. Ele soa bem mesmo em tamanhos pequenos, mas alguns players e sons de carro só aceitam MP3.`],
  [`WAV audio`, `Áudio WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV é áudio sem compressão (geralmente PCM) usado em gravação e edição. Soa exatamente como a fonte, mas ocupa cerca de 10 MB por minuto em qualidade de CD.`],
  [`FLAC lossless audio`, `Áudio FLAC sem perdas`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC é áudio comprimido sem perdas: reduz os arquivos a cerca de metade do tamanho do WAV sem perder nenhuma qualidade, o que o torna o formato favorito para bibliotecas de música e downloads em alta resolução.`],

  // Subtitles
  [`Subtitles`, `Legendas`],
  [`subtitles`, `legendas`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML e MicroDVD entre si, sem nenhum motor, salvos em UTF-8; SSA e SCC são lidos. Arquivos SMI e SRT coreanos em CP949 são lidos corretamente. Legendas dentro de um vídeo são extraídas com o FFmpeg.`],
  [`SubRip subtitles`, `Legendas SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) é o arquivo de legenda mais comum: blocos numerados com tempo de início e fim e texto simples. Quase todo player, editor e site de vídeo o aceita.`],
  [`Advanced SubStation Alpha subtitles`, `Legendas Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha) é o formato de legenda estilizada dos fansubs de anime e do Aegisub, com fontes, cores, posições e efeitos. Muitos dispositivos e sites só aceitam SRT simples.`],
  [`WebVTT subtitles`, `Legendas WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt) é o formato de legenda do vídeo HTML5. Players web, o YouTube e plataformas de cursos online o usam.`],
  [`SAMI subtitles (SMI)`, `Legendas SAMI (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi) é o formato de legenda da Microsoft parecido com HTML. Ainda é o arquivo de legenda clássico na Coreia, muitas vezes salvo na antiga codificação CP949, que players mais novos mostram como texto corrompido.`],

  // Archives
  [`Archives`, `Arquivos compactados`],
  [`archives`, `arquivos compactados`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `Reempacote ou extraia ZIP, 7Z, RAR, TAR, imagens de disco e muitos outros formatos de arquivo compactado com o motor 7-Zip incluído, ou compacte quaisquer arquivos em um único ZIP.`],
  [`ZIP archive`, `Arquivo ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP é o formato universal de arquivo compactado. Windows, macOS, celulares e quase todo formulário de upload o abrem sem programas extras.`],
  [`7-Zip archive`, `Arquivo 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z é o formato aberto de arquivo compactado do 7-Zip. Sua compressão LZMA2 geralmente gera arquivos menores que o ZIP, mas nem todo sistema ou site consegue abri-lo.`],
  [`RAR archive`, `Arquivo RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR é o formato proprietário de arquivo compactado do WinRAR, comum em downloads divididos em partes. As versões recentes do Windows 11 abrem RAR, mas não conseguem criá-lo, e muitas ferramentas só aceitam ZIP.`],
  [`Any files`, `Qualquer arquivo`],

  // CAD
  [`CAD drawings`, `Desenhos CAD`],
  [`CAD drawings [in running text]`, `desenhos CAD`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `DWG e DXF do AutoCAD: converta entre eles ou para PDF, SVG e PNG, sem o AutoCAD.`],
  [`AutoCAD drawing`, `Desenho do AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG é o formato de desenho nativo do AutoCAD e o arquivo CAD mais comum em arquitetura e engenharia. Sem o AutoCAD ou um visualizador de DWG, é difícil abri-lo ou compartilhá-lo.`],
  [`Drawing Exchange Format`, `Formato de intercâmbio de desenhos`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format) é o formato de intercâmbio da Autodesk para desenhos CAD. Cortadoras a laser, softwares de CNC e a maioria dos programas CAD o leem, por isso é o jeito usual de levar desenhos de uma ferramenta para outra.`],

  // 3D
  [`3D models`, `Modelos 3D`],
  [`3D models [in running text]`, `modelos 3D`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF e PLY entre si, e FBX para qualquer um deles, com cores, texturas e materiais quando o formato os mantém, e para uma imagem PNG ou JPG sombreada. Não é preciso instalar nada.`],
  [`glTF binary (GLB)`, `glTF binário (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB é a versão em arquivo único do glTF, o formato 3D da web, da realidade aumentada e dos motores de jogos. Malhas, materiais e texturas ficam reunidos em um só arquivo compacto.`],
  [`STL 3D model`, `Modelo 3D STL`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL é o arquivo clássico para impressão 3D. Ele guarda só os triângulos de uma forma, sem cores nem unidades, e todo fatiador e programa CAD o lê.`],
  [`Wavefront OBJ model`, `Modelo Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront) é um formato 3D em texto simples que quase todo programa 3D abre. Materiais e texturas ficam ao lado dele, em um arquivo .mtl e em imagens.`],

  // Fonts
  [`Fonts`, `Fontes`],
  [`fonts`, `fontes`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Fontes para desktop e web: TTF, OTF, WOFF, WOFF2 e EOT entre si.`],
  [`TrueType font`, `Fonte TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType) é o formato de fonte para desktop mais comum no Windows e no macOS. Instale o arquivo para usar a fonte em qualquer app.`],
  [`OpenType font`, `Fonte OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType) é um formato de fonte da Adobe e da Microsoft. Fontes OpenType com contornos PostScript (CFF) são comuns em tipos profissionais e suportam recursos como ligaduras.`],
  [`Web font (WOFF2)`, `Fonte web (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 é o formato comprimido de fonte web suportado por todos os navegadores modernos. Costuma ser cerca de 30% menor que o WOFF, então as páginas carregam mais rápido.`],

  // Geospatial
  [`Geospatial data`, `Dados geoespaciais`],
  [`geospatial data`, `dados geoespaciais`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Mapas e dados de GPS: GeoJSON, KML, KMZ, GPX e Shapefile entre si e para CSV, Excel e JSON, e um CSV com coordenadas de volta para um arquivo de mapa. Apenas dados vetoriais (pontos, linhas e áreas), sempre salvos em longitude e latitude. Não é preciso instalar nada.`],
  [`one row per feature, with its coordinates`, `uma linha por feição, com as coordenadas`],
  [`a CSV with longitude and latitude columns or WKT`, `um CSV com colunas de longitude e latitude ou WKT`],

  // Camera RAW
  [`Camera RAW photo`, `Foto RAW de câmera`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Arquivos RAW de câmera (CR2, CR3, NEF, ARW, DNG, RAF, ORF e outros) guardam os dados brutos do sensor de uma foto. Eles preservam o máximo de detalhes para edição, mas são grandes e precisam de um programa específico para serem visualizados.`],

  // Conversion guides
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `JPG é a escolha segura quando um site, um app antigo do Windows ou alguém sem iPhone precisa das suas fotos. Um lote inteiro de fotos HEIC é convertido de uma vez, e cada JPG é salvo ao lado do original.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Escolha PNG quando quiser continuar editando a foto sem acrescentar mais uma rodada de compressão JPG. O PNG é sem perdas, então espere arquivos várias vezes maiores que o HEIC original.`],

  // Conversion guides
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `O HEIC guarda uma foto em cerca de metade do espaço de um JPG com a mesma qualidade, e é assim que os iPhones salvam as fotos. Salvar em HEIC exige o motor gratuito FFmpeg (cerca de 100 MB, baixado uma única vez no app). EXIF, perfil de cor e orientação são mantidos.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Imagens salvas de sites costumam ser WebP. Converter para PNG mantém a qualidade total e qualquer transparência, então o resultado funciona em qualquer editor, apresentação e documento.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Escolha JPG quando a imagem for uma foto e o tamanho do arquivo importar, por exemplo em formulários de envio que recusam WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `Capturas de tela e fotos exportadas em PNG podem ter muitos megabytes. Fotos costumam ficar bem menores em JPG; para capturas de tela com muito texto e para logotipos, o PNG muitas vezes continua sendo o melhor formato.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Converter JPG em PNG não recupera os detalhes perdidos na compressão do JPG, mas impede novas perdas: cada edição e cada salvamento posterior ficam sem perdas. Converta antes de retocar uma imagem ou de adicionar transparência num editor.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Imagens AVIF de sites modernos e de celulares não abrem em muitos programas antigos, visualizadores de imagem e formulários de envio. O JPG abre em qualquer lugar, ao custo de arquivos um pouco maiores.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `O WebP é ideal para sites: as fotos ficam bem menores que em JPG e os gráficos mantêm a transparência. A predefinição WEBP salva com qualidade 85, um bom equilíbrio para a web.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Páginas escaneadas, recibos e fotos de documentos muitas vezes precisam ser enviados como um único PDF. Solte as imagens na predefinição de mesclagem para obter um só PDF, ou em PDF para obter um PDF por imagem. Por padrão, cada página fica com o tamanho da sua imagem.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Um único ICO cobre tudo o que o Windows precisa para os ícones da área de trabalho, do Explorador e da barra de tarefas, e também funciona como favicon de site. Comece com um PNG quadrado de pelo menos 256×256 px para ter o resultado mais nítido.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Criar um ícone de app para Mac no Windows normalmente exige ferramentas extras; o Filee transforma um PNG em ICNS diretamente. Use um PNG quadrado de 1024×1024 px para que os tamanhos Retina fiquem nítidos.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Compartilhe um design do Photoshop com quem não tem Photoshop: o PNG mostra a imagem como foi salva, com as camadas visíveis combinadas e a transparência mantida. O PNG não guarda camadas, então mantenha o PSD para editar.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `O Filee lê os arquivos RAW de Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One e outras, e os revela com as configurações padrão. É o jeito rápido de tirar de uma sessão de fotos JPGs prontos para compartilhar; para edição criativa, use antes um editor de RAW.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Solte de uma vez os CR2 de um cartão de memória inteiro: o Filee converte tudo em paralelo e salva cada JPG ao lado do seu arquivo RAW. As câmeras Canon mais novas gravam CR3, que o Filee também lê.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `Arquivos NEF são grandes e incomuns demais para enviar como estão. Em JPG, viram fotos pequenas que abrem em qualquer lugar; use JPG 70% ou Reduzir 50% para apps de mensagens. Os arquivos NRW das câmeras Coolpix da Nikon funcionam do mesmo jeito.`],
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Muitos apps, apresentações e formulários de envio não aceitam SVG. O Filee renderiza o desenho vetorial num PNG com transparência; arquivos SVGZ compactados também funcionam.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `De SVG para PDF, tudo continua vetorial: linhas e textos ficam nítidos em qualquer zoom e na impressão, e o arquivo continua pequeno. Prático para enviar logotipos e diagramas a uma gráfica ou colocá-los em documentos.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS só pode ser exibido por um interpretador PostScript; o Filee usa o Ghostscript para isso. O PDF mantém a arte vetorial, então abre em qualquer lugar e continua saindo nítido na impressão. Arquivos PostScript (.ps) funcionam do mesmo jeito.`],
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Cada página vira um JPG, então um PDF de 10 páginas gera 10 imagens. Prático para chats, slides e posts em redes sociais que aceitam imagens, mas não PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `O PNG mantém textos e linhas nítidos, sem os artefatos do JPG, o que combina com slides, diagramas, partituras e páginas que você quer anotar ou colocar numa apresentação.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `O Filee transforma o PDF num documento do Word com parágrafos de verdade, em vez de imagens das páginas, para você corrigir erros de digitação ou reaproveitar o texto. Layouts complexos podem precisar de ajustes, e um PDF escaneado que só contém imagens das páginas não tem texto para extrair.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `O Filee faz PDF → Word → EPUB sozinho, para que o texto se ajuste à tela de um celular ou de um leitor de e-books. Funciona melhor com PDFs que têm texto de verdade. Os títulos saem como parágrafos comuns, e páginas escaneadas não têm texto para converter.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `O Filee leva o texto do PDF para um documento do Word, grava-o como HWPX e depois o salva como HWP, tudo com motores integrados. Funciona com PDFs que têm texto de verdade. Layouts complexos podem precisar de ajustes, e páginas escaneadas não têm texto para extrair.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `O Filee transforma o PDF primeiro num documento do Word e depois em Markdown, mantendo parágrafos, títulos e negrito sempre que consegue distingui-los. Útil para anotações, wikis ou para colar o texto em outras ferramentas. Páginas escaneadas não têm texto para converter.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Escritórios coreanos muitas vezes exigem documentos no formato Hangul. O Filee converte o texto do PDF num arquivo HWPX que você pode abrir e editar no Hancom Hangul, sem precisar do Hancom Office para a conversão; depois, transforme-o em HWP se algum formulário exigir o formato antigo.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Prático quando um PDF precisa ser mostrado no PowerPoint ou adicionado a uma apresentação existente: cada página vira um slide idêntico ao PDF, e o texto da página fica nas anotações do orador. Os slides são imagens; para mudar o texto, converta o PDF em DOCX.`],
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Sem Microsoft Word nem LibreOffice: o Filee lê o DOCX por conta própria e monta as páginas com cabeçalhos, rodapés, tabelas e imagens. Solte vários documentos na predefinição de mesclagem para juntá-los num só PDF.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Documentos antigos do Word 97–2003 vindos de acervos, formulários oficiais ou sistemas legados viram PDFs que abrem em qualquer lugar. O mesmo motor também converte arquivos ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord e Apple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Salve e-mails como PDF para registros, faturas ou documentação jurídica: o PDF mostra remetente, destinatários, data, assunto e mensagem, e abre em qualquer lugar sem um app de e-mail.`],
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `O Filee renderiza as páginas HWP com o rhwp, um motor Hangul de código aberto, sem envolver o Hancom Office nem a janela de autorização dele. Útil para enviar documentos coreanos a pessoas que não conseguem abrir HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Transforme um documento Hangul num arquivo do Word que colegas no exterior possam editar. Texto, parágrafos e tabelas são transferidos; layouts com muitos objetos flutuantes merecem uma conferida rápida no Word.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `O HWPX, o formato Hangul mais novo baseado em XML, é convertido como o HWP: o motor integrado rhwp monta as páginas, totalmente offline. Prático para arquivar como PDF formulários HWPX de órgãos públicos.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Alguns sistemas e fluxos de trabalho mais novos só aceitam HWPX. O Filee converte HWP binário em HWPX com o rhwp, sem Hancom Office, e converte um lote inteiro de documentos antigos de uma vez.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Versões mais antigas do Hangul e alguns portais de envio ainda esperam .hwp. O Filee converte HWPX de volta para HWP com o rhwp, para você não ter que abrir e salvar de novo cada arquivo no Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `O gravador de HWPX próprio do Filee transfere o layout do Word: tamanho de página e margens, cabeçalhos e rodapés com números de página, tabelas com células mescladas, bordas e sombreamento, caixas de texto, formas e imagens. Nos testes, cada arquivo que ele grava é verificado com três leitores de HWPX independentes.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Para escritórios e formulários que ainda pedem .hwp. O Filee grava o documento do Word como HWPX com seu próprio gravador e converte esse arquivo em HWP com o rhwp, ambos integrados, então o Hancom Office não é necessário para a conversão.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Cada página do documento do Word vira um JPG (o Filee primeiro monta o documento como PDF), prático para publicar uma página na internet ou enviar uma prévia rápida. Não é preciso ter o Word.`],
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Cada planilha visível vira uma seção própria, com formatos de número, fontes, preenchimentos, bordas e células mescladas como o Excel mostra. Planilhas largas são ajustadas à largura da página, como em “Ajustar Todas as Colunas em Uma Página” do Excel, e as linhas de cabeçalho congeladas se repetem em todas as páginas.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `O CSV guarda uma única tabela, então o Filee grava um CSV por planilha. As células são exportadas como valores, prontas para bancos de dados, scripts e formulários de importação.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Uma pasta de trabalho XLSX pode guardar a formatação, as fórmulas e as planilhas extras que o CSV não comporta. Selecione todos os seus CSV exportados e solte-os de uma vez para obter uma pasta de trabalho por arquivo, sem a caixa de diálogo de importação do Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Atualize pastas de trabalho antigas do Excel 97–2003 sem Excel nem LibreOffice: a conversão é integrada. Arquivos XLSX costumam ser menores, não podem conter macros e abrem em qualquer app de planilhas atual.`],
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Cada slide vira uma página de PDF do tamanho do slide, com texto, formas, imagens, tabelas e o design do slide mestre. Prático para distribuir apresentações ou enviá-las onde arquivos do PowerPoint não são aceitos. Animações e anotações do orador não entram no PDF.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Apresentações antigas do PowerPoint 97–2003 viram PDFs que qualquer pessoa pode abrir, imprimir ou enviar. Apresentações Keynote (.key), ODP e WPS (DPS) são convertidas do mesmo jeito.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Cada slide vira um JPG, pronto para posts em redes sociais, miniaturas, mensagens de chat ou um editor de vídeo. Escolha PNG se os slides tiverem muito texto pequeno.`],
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Títulos, listas (inclusive listas de tarefas), tabelas, código, citações, links, imagens, notas de rodapé e fórmulas matemáticas são diagramados em páginas A4, sem Pandoc, LaTeX nem navegador. Um jeito rápido de compartilhar anotações e arquivos README com quem não lê Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Integrado, sem precisar do Pandoc. Títulos, listas, tabelas, links e notas de rodapé são mantidos, para você continuar editando o documento e mudando o estilo dele no Word.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Texto simples vira um PDF A4 limpo, com um parágrafo por linha. O Filee reconhece UTF-8 e UTF-16, além de arquivos de texto coreanos antigos (CP949), para que logs e anotações antigos não virem caracteres embaralhados.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Salve uma página da web ou um relatório HTML como um PDF que fica igual em qualquer lugar e pode ser arquivado ou impresso. O Filee converte arquivos .html salvos no seu PC, e vários deles podem ser mesclados num só PDF.`],
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `Um PDF mantém um layout de página fixo, o que é prático para imprimir um e-book, lê-lo no PC ou enviá-lo a um aparelho sem leitor de EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Passe uma biblioteca antiga de Kindle/Mobipocket para EPUB, para que ela abra no Apple Books, Google Play Livros, Kobo e na maioria dos apps de leitura. Essa direção é integrada, então o Calibre não é necessário.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `Quem grava os arquivos MOBI e AZW3 é o Calibre, uma ferramenta de e-books. Os Kindles atuais também aceitam EPUB pelo Send to Kindle, então o MOBI é útil principalmente para aparelhos e apps Kindle mais antigos.`],
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Salve o áudio de uma aula, de um show ou de uma entrevista como um MP3 que toca em qualquer lugar: no carro, num player antigo ou numa ferramenta de transcrição.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `Vídeos do iPhone e do Mac são arquivos MOV. Em MP4, eles tocam em celulares Android, smart TVs, apps antigos do Windows e formulários de envio que recusam MOV. O vídeo e o som normalmente cabem no MP4 como estão, então o Filee só os reempacota: sem perda de qualidade, HDR mantido, pronto em segundos. A predefinição MP4 720p reduz clipes 4K para compartilhar.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Gravações em MKV, por exemplo do OBS, muitas vezes não podem ser importadas em editores de vídeo nem tocam em TVs, enquanto o MP4 é aceito quase em todo lugar. A conversão é feita localmente, então gravações longas nunca precisam ser enviadas para a internet.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Gravações de tela e vídeos salvos do navegador costumam ser WebM, um formato com que muitos editores de vídeo, players antigos e apps de mensagens se dão mal. O MP4 toca quase em todo lugar, e um lote inteiro de clipes é convertido de uma vez.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Transforme um clipe curto num GIF animado para chats, documentação ou relatórios de bugs. Mantenha-o curto: o GIF guarda cada quadro como uma imagem de 256 cores, então vídeos longos ou de alta resolução geram arquivos muito grandes.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Um vídeo solto em JPG gera uma única imagem parada. Para escolher uma miniatura ou percorrer um clipe quadro a quadro, use a predefinição Extrair quadros (JPG): as imagens vão para uma pasta ao lado do vídeo, todos os quadros ou um a cada N. Um vídeo que geraria mais de 100.000 imagens ou encheria o disco é recusado antes de começar.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `Arquivos AVI de filmadoras e câmeras antigas são grandes e muitas vezes usam codecs que celulares e TVs não reproduzem mais. Um MP4 com compressão moderna costuma ser bem menor e toca em qualquer lugar.`],
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Uma gravação WAV ocupa cerca de 10 MB por minuto; em MP3, ela precisa de uma fração disso e continua tocando em qualquer aparelho.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Mantenha sua biblioteca FLAC sem perdas em casa e coloque cópias em MP3 no celular, num pen drive para o carro ou num player antigo que não toca FLAC. Álbuns inteiros são convertidos de uma vez.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `Gravações de voz do iPhone, downloads do iTunes sem DRM e muitos gravadores geram M4A. O MP3 é aceito por qualquer player, som automotivo e formulário de envio.`],
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Reempacote arquivos RAR como ZIP para pessoas, formulários de envio e sistemas que só aceitam ZIP. Não é preciso ter o WinRAR, nem para ler o RAR nem para gravar o ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `O 7Z costuma compactar melhor, mas o ZIP abre em qualquer computador ou celular sem software extra. Converta quando for enviar um arquivo compactado para alguém que não tem o 7-Zip.`],
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Envie desenhos a clientes, equipes de obra ou gráficas que não têm AutoCAD: um PDF abre em qualquer PC ou celular. Vários desenhos podem ser mesclados num só PDF.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `Arquivos DXF de programas CAD, trabalhos de corte a laser ou trocas de projetos viram PDFs que qualquer pessoa pode abrir e imprimir. SVG e PNG também estão disponíveis, por exemplo para prévias na web.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `O DXF é o formato de intercâmbio que cortadoras a laser, softwares CNC e a maioria dos programas CAD leem. Converter DWG em DXF permite abrir desenhos do AutoCAD nessas ferramentas, e de DXF de volta para DWG também funciona.`],
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Hospede uma fonte no seu próprio site: o WOFF2 é o formato compactado de fontes para a web que todo navegador moderno suporta, normalmente cerca de 30% menor que o WOFF. Verifique se a licença da fonte permite a incorporação na web.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Alguns programas antigos, máquinas de corte e de bordado e motores de jogo só aceitam fontes TrueType. Converta uma família inteira de fontes OTF em TTF de uma vez, sem editor de fontes.`],
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Use Traço em SVG para logotipos, assinaturas e digitalizações: a tinta vira uma única forma preta sobre fundo transparente. Vetorizar em SVG mantém até 64 cores para ícones e ilustrações. Fotos saem como manchas de cor chapada, então a vetorização funciona melhor com desenhos.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `Um JPG de um logotipo ou de um esboço escaneado vira um SVG que fica nítido em qualquer tamanho, pronto para uma plotter de recorte, um site ou uma gráfica. O ruído do JPG vira pontinhos, então diminua a configuração Detalhe na predefinição se o resultado parecer poluído.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Cortadoras a laser, softwares CNC e programas CAD leem DXF. O Filee grava os contornos do SVG em milímetros, então uma forma de 100 mm de largura continua com 100 mm. Curvas viram polilinhas finas. Preenchimentos, imagens e filtros ficam de fora.`],
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `E-mails arrastados do Outlook são arquivos MSG que só o Outlook abre. Em PDF, eles mantêm remetente, destinatários, data, assunto e mensagem, e abrem em qualquer lugar. Não é preciso ter o Outlook.`],
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `O YAML é mais fácil de ler e editar à mão, e por isso é usado em arquivos de configuração. As chaves mantêm a ordem, e textos que seriam lidos de volta como número ou como true/false ficam entre aspas.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Transforme um arquivo de configuração em JSON para uma API, um script ou uma ferramenta que só lê JSON. Âncoras e aliases são resolvidos, e um arquivo com vários documentos vira um único array. Os comentários são descartados, já que o JSON não tem comentários.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Uma lista de registros em JSON vira uma tabela que você pode abrir no Excel: uma linha por registro, uma coluna por chave. Se os registros estiverem dentro de um invólucro como {"users": […]}, o Filee os encontra. Dados que não formam uma tabela interrompem a conversão com uma mensagem, em vez de gerar um arquivo corrompido.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Leve uma agenda de contatos para o Excel ou para uma ferramenta de e-mail em massa: uma linha por contato, com nome, organização, e-mail, telefone, endereço e aniversário. Contatos de celulares coreanos antigos em CP949 são lidos corretamente.`],
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Players web e plataformas de cursos on-line exigem WebVTT. Tempos, quebras de linha e itálico são mantidos, e nenhum motor é necessário.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Muitos players, TVs e editores não leem SMI, e arquivos SMI coreanos antigos costumam aparecer com o texto ilegível. O Filee detecta CP949, escolhe o idioma com mais linhas e salva um SRT limpo em UTF-8.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Quando uma TV, um celular ou um site de vídeos recusa legendas ASS com estilo, o SRT simples funciona. Negrito, itálico, sublinhado e cores são mantidos; posições, fontes e efeitos são descartados.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Tire as legendas de um filme para editá-las ou traduzi-las. A primeira faixa de legendas em texto é salva como SRT; legendas em imagem (DVD, Blu-ray) não podem ser convertidas em texto. Exige o motor gratuito FFmpeg.`],
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Abra um arquivo de impressão 3D num programa 3D que prefere OBJ. O STL não tem unidades, então o Filee o lê em milímetros e grava o OBJ também em milímetros, com o eixo Y apontando para cima, como na maioria dos programas 3D.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Os fatiadores de impressoras 3D usam STL. Faces de qualquer formato são divididas em triângulos, e o Y para cima vira Z para cima, para que um modelo vertical fique de pé na mesa de impressão. O STL guarda só a forma, então cores e texturas ficam no OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Leve um modelo da web ou de um motor de jogo para um programa que lê OBJ. O arquivo .mtl e as texturas são gravados ao lado do .obj, então mantenha-os juntos.`],

  // FAQ
  [`Is Filee really free?`,
    `O Filee é mesmo gratuito?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Sim. O Filee é gratuito e de código aberto, sob a licença MIT: sem anúncios, sem marcas d'água, sem conta, sem período de teste e sem limites próprios de quantidade ou de tamanho de arquivos.`],
  [`Does it work offline? Are my files uploaded?`,
    `Funciona offline? Meus arquivos são enviados para a internet?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Toda conversão é feita no seu próprio PC, e os arquivos nunca são enviados. A internet só é usada para baixar um motor opcional ou verificar atualizações, então documentos confidenciais, fotos e gravações ficam no seu computador.`],
  [`Which file formats does Filee support?`,
    `Quais formatos de arquivo o Filee suporta?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `O Filee lê {formatTotal} formatos de arquivo em {categoryCount} categorias: {categoryList}. {builtinTotal} deles funcionam logo após a instalação; os outros usam um motor opcional gratuito. O catálogo de formatos lista cada formato e para quais formatos ele converte.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Preciso do Microsoft Office, do Hancom Office ou do LibreOffice?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF.`,
    `Não. Arquivos do Word, Excel e PowerPoint (DOCX, XLSX, XLS, CSV, PPTX) e documentos coreanos HWP/HWPX são convertidos por motores integrados ao Filee. O Filee não usa o Office nem o Hancom Office, mesmo que estejam instalados; o LibreOffice é apenas um download opcional dentro do app para formatos mais antigos, como DOC, PPT, ODT e RTF.`],
  [`What are the optional engines?`,
    `O que são os motores opcionais?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Os motores grandes não vêm no instalador. Marque-os na página de motores do instalador ou baixe-os dentro do Filee quando precisar: {engineDetails}. Eles ficam salvos na pasta do próprio Filee e podem ser removidos a qualquer momento, e o app mostra as versões, a velocidade de download e o tempo restante. Se o FFmpeg, o calibre, o Pandoc, o Ghostscript ou o LibreOffice já estiver no seu PC (no PATH, inclusive pelo Scoop, ou em Program Files), o Filee usa essa cópia e pula o download, e avisa quando ela é mais antiga que a versão com que o Filee foi testado. Em Configurações → Motores → Usar minha cópia você escolhe uma cópia específica.`],
  [`Does installing Filee need administrator rights?`,
    `Instalar o Filee exige direitos de administrador?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Só uma vez, durante a instalação. O instalador coloca o Filee em Program Files para todos os usuários e, no Windows 11, adiciona “Converter com o Filee” ao topo do menu do Explorador de Arquivos. Depois disso, o Filee roda como seu usuário normal. Para instalações silenciosas, execute o instalador com /VERYSILENT /SUPPRESSMSGBOXES. Se você não puder instalar programas, use o ZIP portátil: descompacte-o em qualquer lugar e execute o Filee.exe.`],
  [`Can I convert many files at once?`,
    `Posso converter vários arquivos de uma vez?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Sim. Selecione quantos arquivos quiser e solte todos de uma vez: o Filee converte em paralelo, um arquivo com falha nunca interrompe os outros, e as predefinições podem mesclar tudo num só PDF ou compactar tudo num só ZIP.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `Posso converter pelo menu do botão direito do Windows 11?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Sim. Clique com o botão direito nos arquivos no Explorador de Arquivos e escolha “Converter com o Filee”. No Windows 11, você também pode colocar essa opção no menu principal, sem passar por “Mostrar mais opções”: clique uma vez em “Adicionar ao menu principal” em Configurações → Geral e aprove o pedido de administrador. Enviar para, um atalho de teclado e a área de soltar da janela principal também funcionam.`],
  [`Can Filee convert from the command line or automatically?`,
    `O Filee converte pela linha de comando ou automaticamente?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Sim. A instalação pode adicionar o comando filee ao PATH: filee convert *.heic --to jpg converte arquivos, curingas e pastas com as suas predefinições, imprime JSON para scripts e retorna códigos de saída. As pastas monitoradas convertem automaticamente os arquivos que chegam a uma pasta e podem mover os originais para outro lugar. Configure-as na página Pastas monitoradas do app ou com filee watch num terminal.`],
  [`How do I convert a file, for example HEIC to JPG?`,
    `Como converto um arquivo, por exemplo, de HEIC para JPG?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Selecione os arquivos no Explorador de Arquivos, segure Ctrl (ou a tecla que você escolheu) e arraste-os. Um menu circular de formatos se abre no cursor: solte os arquivos em JPG e os novos arquivos aparecem ao lado dos originais. Há guias passo a passo para as conversões mais comuns.`],
  [`Why use Filee instead of an online converter?`,
    `Por que usar o Filee em vez de um conversor on-line?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Conversores on-line enviam seus arquivos para o servidor de outra pessoa, muitas vezes limitam o tamanho e a quantidade de arquivos e dependem de uma conexão rápida. O Filee converte no seu PC: arquivos privados continuam privados, vídeos grandes e centenas de arquivos não são problema, e ele funciona sem internet, de graça e sem anúncios.`],
  [`Which operating systems are supported?`,
    `Quais sistemas operacionais são suportados?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Windows 10 e 11 (64 bits) e Linux (x64 e ARM64, Ubuntu 22.04 ou posterior) têm versões completas. No Linux, o gesto de arrastar precisa de uma sessão X11; no KDE Plasma com Wayland ele é experimental, e nos outros desktops Wayland funcionam a área de soltar e o menu do botão direito do gerenciador de arquivos. O macOS 13 ou posterior (Apple silicon e Intel) está em prévia: o app ainda não é notarizado, então o macOS pede que você o permita uma vez em Privacidade e Segurança. Escolha seu sistema na seção de download.`],
]);
